 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 0 and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            components.append(comp)
    out = [row[:] for row in grid]
    if components:
        biggest = max(components, key=len)
        smallest = min(components, key=len)
        for r, c in biggest:
            out[r][c] = 8
        for r, c in smallest:
            out[r][c] = 7
    return out
